import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as dummy } from '@/primitives';
import { createText as dummyText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Color } = ctx.THREE;

  const root = new Group();

  // ----- Geometry & Material -----
  const aspect = 320 / 512; // height / width based on atlas source rect
  const geometry = new PlaneGeometry(1, aspect);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // ----- Load Texture -----
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ----- Text Content -----
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const textGroup = new Group();
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize || 39,
      color: config.intent?.visualSpec?.colors?.paper || '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.set(0, 0, 0.01);
    textGroup.add(txt);
  }
  root.add(textGroup);

  // ----- Cinematic Primitives -----
  const primitiveRefs = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const ref = fn(root, prim.params || {});
      primitiveRefs.push(ref);
    }
  }

  // ----- Interaction Timelines -----
  const liftTimeline = gsap.timeline({ paused: true });
  liftTimeline.to(
    mesh.position,
    { y: mesh.position.y + 0.15, duration: 0.7, ease: 'power3.out' }
  );

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline
    .to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    })
    .to(mesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.09,
      ease: 'back.out(1.7)',
    });

  // ----- Event Handlers -----
  root.userData.handlers = {};

  // hover: true = enter, false = leave
  root.userData.handlers.hover = (enter) => {
    if (enter) {
      liftTimeline.play();
    } else {
      liftTimeline.reverse();
    }
  };

  // click
  root.userData.handlers.click = () => {
    pressTimeline.restart();
    ctx.emit('hub-journal.select', {});
  };

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    // dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // kill GSAP timelines
    liftTimeline.kill();
    pressTimeline.kill();

    // primitive cleanups
    for (const ref of primitiveRefs) {
      if (ref && typeof ref.cleanup === 'function') {
        ref.cleanup();
      }
    }

    // dispose children (texts)
    textGroup.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
    });
  };

  return root;
}
